/*
 * test_civil.c - tests of frc_civil.c: the Gregorian translation of an instant
 * (frc_civil_from_time, frc_time_from_civil, frc_format_civil) and the calendar
 * repair of SPEC S2.3 (frc_julian_fields_to_unix_ms).
 *
 * Expected values come from three places:
 *   1. tests/vectors/oracle_civil.h, generated by tools/oracle/generate-ladder.mjs
 *      and checked there against the JavaScript Date. EVERY row is checked.
 *   2. A calendar walked here one day at a time with nothing but the leap-year
 *      rule: 5.6 million consecutive days, years -4875 .. 10457.
 *   3. Closed forms and round trips: the Julian / Gregorian difference
 *      floor(Y/100) - floor(Y/400) - 2, fields -> instant -> fields.
 *
 * Nothing here uses floating point, so the file is the same in every variant.
 */
#include "frc_test.h"

#include "fractonica.h"
#include "vectors/oracle_civil.h"

#define DAY_US INT64_C(86400000000)
#define DAY_MS INT64_C(86400000)

/* splitmix64: a fixed-seed generator, so a failure reproduces. */
static uint64_t rng_state = UINT64_C(0xC1F11C0DE0000001);
static uint64_t rng(void)
{
    uint64_t z = (rng_state += UINT64_C(0x9E3779B97F4A7C15));
    z = (z ^ (z >> 30)) * UINT64_C(0xBF58476D1CE4E5B9);
    z = (z ^ (z >> 27)) * UINT64_C(0x94D049BB133111EB);
    return z ^ (z >> 31);
}
/* A random value in lo .. hi. */
static int64_t rng_between(int64_t lo, int64_t hi)
{
    return lo + (int64_t)(rng() % (uint64_t)(hi - lo + 1));
}

static frc_civil_t civil(int32_t year, unsigned month, unsigned day, unsigned hour, unsigned minute,
                         unsigned second, uint32_t microsecond)
{
    frc_civil_t c;
    c.year = year;
    c.month = (uint8_t)month;
    c.day = (uint8_t)day;
    c.hour = (uint8_t)hour;
    c.minute = (uint8_t)minute;
    c.second = (uint8_t)second;
    c.weekday = 0;
    c.microsecond = microsecond;
    return c;
}

#define CHECK_CIVIL(c, y, mo, d, h, mi, s, us, wd)                              \
    do {                                                                        \
        CHECK_EQ_I64((c).year, (y));                                            \
        CHECK_EQ_U64((c).month, (mo));                                          \
        CHECK_EQ_U64((c).day, (d));                                             \
        CHECK_EQ_U64((c).hour, (h));                                            \
        CHECK_EQ_U64((c).minute, (mi));                                         \
        CHECK_EQ_U64((c).second, (s));                                          \
        CHECK_EQ_U64((c).microsecond, (us));                                    \
        CHECK_EQ_U64((c).weekday, (wd));                                        \
    } while (0)

/* ------------------------------------------------------------------------- */
/* The oracle                                                                 */
/* ------------------------------------------------------------------------- */

static void test_oracle_civil(void)
{
    char buf[64];
    unsigned i;

    TEST_SECTION("oracle_civil: fields, instant and ISO text");
    for (i = 0; i < ORACLE_CIVIL_COUNT; i++) {
        const oracle_civil_t *v = &oracle_civil[i];
        frc_civil_t got, fields;

        memset(&got, 0xEE, sizeof got);
        frc_civil_from_time(v->t_us, v->utc_offset_s, &got);
        CHECK_CIVIL(got, v->year, v->month, v->day, v->hour, v->minute, v->second, v->microsecond,
                    v->weekday);
        CHECK_NOTE("civil vector %u: t = %" PRId64 " offset %d (%s)", i, v->t_us, v->utc_offset_s, v->iso);

        /* the fields of the vector, not the ones just computed: the two directions are tested apart */
        fields = civil(v->year, v->month, v->day, v->hour, v->minute, v->second, v->microsecond);
        fields.weekday = 99; /* output only: must be ignored */
        CHECK_EQ_I64(frc_time_from_civil(&fields, v->utc_offset_s), v->t_us);
        CHECK_NOTE("civil vector %u back: %s", i, v->iso);

        CHECK_EQ_I64(frc_format_civil(&fields, v->utc_offset_s, buf, sizeof buf), (int)strlen(v->iso));
        CHECK_STR(buf, v->iso);
    }
}

static void test_oracle_roll(void)
{
    unsigned i, kinds[3] = {0, 0, 0};

    TEST_SECTION("oracle_civil_roll: fields that overflow");
    for (i = 0; i < ORACLE_CIVIL_ROLL_COUNT; i++) {
        const oracle_civil_roll_t *v = &oracle_civil_roll[i];
        frc_civil_t fields = civil(v->year, v->month, v->day, v->hour, v->minute, v->second, v->microsecond);
        CHECK_EQ_I64(frc_time_from_civil(&fields, v->utc_offset_s), v->t_us);
        CHECK_NOTE("roll vector %u (kind %u): %d-%u-%u %u:%u:%u.%u offset %d", i, v->kind, v->year, v->month,
                   v->day, v->hour, v->minute, v->second, v->microsecond, v->utc_offset_s);
        kinds[v->kind % 3]++;
    }
    /* all three kinds are present: normal, above the range, month 0 / day 0 */
    CHECK(kinds[ORACLE_CIVIL_ROLL_NORMAL] > 0);
    CHECK(kinds[ORACLE_CIVIL_ROLL_OVERFLOW] > 0);
    CHECK(kinds[ORACLE_CIVIL_ROLL_UNDERFLOW] > 0);
}

/* ------------------------------------------------------------------------- */
/* A calendar walked day by day                                               */
/* ------------------------------------------------------------------------- */

static int is_leap(int32_t year)
{
    /* year may be negative: C's % keeps the sign, which does not matter for "== 0" */
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

static unsigned month_length(int32_t year, unsigned month)
{
    static const uint8_t LENGTH[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    return (month == 2 && is_leap(year)) ? 29u : LENGTH[month - 1];
}

/* Check day number `days` against the walked date, both ways, at a time of day. */
static void check_walked_day(int64_t days, int32_t year, unsigned month, unsigned day, unsigned weekday)
{
    frc_civil_t got, fields;
    /* a different time of day for each day, to the microsecond */
    int64_t within = (int64_t)((uint64_t)days * UINT64_C(2654435761) % (uint64_t)DAY_US);
    frc_time_t t = days * DAY_US + within;

    frc_civil_from_time(t, 0, &got);
    CHECK_EQ_I64(got.year, year);
    CHECK_EQ_U64(got.month, month);
    CHECK_EQ_U64(got.day, day);
    CHECK_EQ_U64(got.weekday, weekday);
    CHECK_NOTE("day %" PRId64 " should be %d-%02u-%02u", days, year, month, day);
    CHECK_EQ_I64((int64_t)got.hour * 3600000000 + (int64_t)got.minute * 60000000
                     + (int64_t)got.second * 1000000 + got.microsecond,
                 within);
    fields = civil(year, month, day, 0, 0, 0, 0);
    CHECK_EQ_I64(frc_time_from_civil(&fields, 0), days * DAY_US);
    CHECK_EQ_I64(frc_time_from_civil(&got, 0), t);
}

static void test_walk(void)
{
    int64_t days;
    int32_t year;
    unsigned month, day, weekday;

    TEST_SECTION("5.6 million consecutive days against the leap-year rule");
    /* forward from 1970-01-01, a Thursday (3) */
    year = 1970;
    month = 1;
    day = 1;
    weekday = 3;
    for (days = 0; days <= 3100000; days++) {
        check_walked_day(days, year, month, day, weekday);
        weekday = (weekday + 1) % 7;
        if (++day > month_length(year, month)) {
            day = 1;
            if (++month > 12) {
                month = 1;
                year++;
            }
        }
    }
    CHECK(year > 10000); /* the walk passed year 9999 */

    /* backward from 1969-12-31, a Wednesday (2) */
    year = 1969;
    month = 12;
    day = 31;
    weekday = 2;
    for (days = -1; days >= -2500000; days--) {
        check_walked_day(days, year, month, day, weekday);
        weekday = (weekday + 6) % 7;
        if (--day == 0) {
            if (--month == 0) {
                month = 12;
                year--;
            }
            day = month_length(year, month);
        }
    }
    CHECK(year < -4800); /* past year 0 and the Julian period's start */
}

/* ------------------------------------------------------------------------- */
/* Offsets, round trips, the ends of frc_time_t                               */
/* ------------------------------------------------------------------------- */

static void test_round_trips(void)
{
    frc_civil_t a, b;
    unsigned i;

    TEST_SECTION("offsets and round trips on random instants");
    for (i = 0; i < 200000; i++) {
        /* years -1200 .. 5100, any microsecond; offsets up to 26 hours either way, to the second */
        frc_time_t t = rng_between(-INT64_C(100000000000000000), INT64_C(100000000000000000));
        int32_t offset = (int32_t)rng_between(-93600, 93600);

        frc_civil_from_time(t, offset, &a);
        CHECK(a.month >= 1 && a.month <= 12 && a.day >= 1 && a.day <= month_length(a.year, a.month));
        CHECK(a.hour <= 23 && a.minute <= 59 && a.second <= 59 && a.microsecond <= 999999 && a.weekday <= 6);
        CHECK_EQ_I64(frc_time_from_civil(&a, offset), t);
        CHECK_NOTE("t = %" PRId64 " offset %d", t, offset);
        /* local fields are the UTC fields of the shifted instant */
        frc_civil_from_time(t + (int64_t)offset * 1000000, 0, &b);
        CHECK(a.year == b.year && a.month == b.month && a.day == b.day && a.hour == b.hour
              && a.minute == b.minute && a.second == b.second && a.weekday == b.weekday
              && a.microsecond == b.microsecond);
    }

    TEST_SECTION("the ends of frc_time_t (computed apart, with 400-year cycles)");
    frc_civil_from_time(INT64_MAX, 0, &a);
    CHECK_CIVIL(a, 294247, 1, 10, 4, 0, 54, 775807, 6);
    frc_civil_from_time(INT64_MIN, 0, &a);
    CHECK_CIVIL(a, -290308, 12, 21, 19, 59, 5, 224192, 6);
    /* the offset is added to the time of day, so even these do not overflow */
    frc_civil_from_time(INT64_MAX, INT32_MAX, &a);
    CHECK_CIVIL(a, 294315, 1, 29, 7, 15, 1, 775807, 4);
    frc_civil_from_time(INT64_MIN, INT32_MAX, &a);
    CHECK_CIVIL(a, -290239, 1, 9, 23, 13, 12, 224192, 4);
    frc_civil_from_time(INT64_MAX, INT32_MIN, &a);
    CHECK_CIVIL(a, 294178, 12, 22, 0, 46, 46, 775807, 1);
    frc_civil_from_time(INT64_MIN, INT32_MIN, &a);
    CHECK_CIVIL(a, -290376, 12, 3, 16, 44, 57, 224192, 1);
    frc_civil_from_time(0, 0, NULL); /* must not crash */
    CHECK(1);

    TEST_SECTION("frc_time_from_civil: the years it accepts");
    a = civil(290000, 1, 1, 0, 0, 0, 0);
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), INT64_C(9089348860800000000));
    a = civil(290000, 12, 31, 0, 0, 0, 0);
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), INT64_C(9089380396800000000));
    a = civil(-290000, 1, 1, 0, 0, 0, 0);
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), -INT64_C(9213683299200000000));
    a = civil(12345, 1, 1, 0, 0, 0, 0);
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), INT64_C(327403382400000000));
    a = civil(-12345, 1, 1, 0, 0, 0, 0);
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), -INT64_C(451737734400000000));
    /* every overflowing field at once at both ends: still inside frc_time_t */
    a = civil(289978, 255, 255, 255, 255, 255, UINT32_MAX); /* month 255 carries 21 years: 289999 */
    CHECK(frc_time_from_civil(&a, INT32_MIN) != FRC_TIME_NONE);
    CHECK(frc_time_from_civil(&a, INT32_MIN) > INT64_C(9089000000000000000));
    a = civil(-290000, 1, 0, 0, 0, 0, 0);
    CHECK(frc_time_from_civil(&a, INT32_MAX) != FRC_TIME_NONE);
    CHECK(frc_time_from_civil(&a, INT32_MAX) < -INT64_C(9213683299200000000));
    /* beyond them the instant would not fit: none, never a wrapped value */
    a = civil(290001, 1, 1, 0, 0, 0, 0);
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), FRC_TIME_NONE);
    a = civil(-290001, 12, 31, 0, 0, 0, 0);
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), FRC_TIME_NONE);
    a = civil(290000, 13, 1, 0, 0, 0, 0); /* the limit is on the year AFTER the month carry */
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), FRC_TIME_NONE);
    a = civil(-290000, 0, 1, 0, 0, 0, 0);
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), FRC_TIME_NONE);
    a = civil(INT32_MAX, 12, 31, 23, 59, 59, 999999);
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), FRC_TIME_NONE);
    a = civil(INT32_MIN, 1, 1, 0, 0, 0, 0);
    CHECK_EQ_I64(frc_time_from_civil(&a, 0), FRC_TIME_NONE);
    a = civil(INT32_MAX, 255, 255, 255, 255, 255, UINT32_MAX);
    CHECK_EQ_I64(frc_time_from_civil(&a, INT32_MIN), FRC_TIME_NONE);
    CHECK_EQ_I64(frc_time_from_civil(NULL, 0), FRC_TIME_NONE);

    TEST_SECTION("frc_time_from_civil is linear in every field");
    for (i = 0; i < 20000; i++) {
        frc_civil_t base = civil((int32_t)rng_between(-3000, 9000), (unsigned)rng_between(1, 12), 1, 0, 0, 0, 0);
        frc_civil_t over = base;
        int64_t start = frc_time_from_civil(&base, 0);
        int32_t offset = (int32_t)rng_between(-50000, 50000);
        over.day = (uint8_t)rng_between(0, 255);
        over.hour = (uint8_t)rng_between(0, 255);
        over.minute = (uint8_t)rng_between(0, 255);
        over.second = (uint8_t)rng_between(0, 255);
        over.microsecond = (uint32_t)rng();
        CHECK_EQ_I64(frc_time_from_civil(&over, offset),
                     start + ((int64_t)over.day - 1) * DAY_US + (int64_t)over.hour * 3600000000
                         + (int64_t)over.minute * 60000000 + (int64_t)over.second * 1000000
                         + (int64_t)over.microsecond - (int64_t)offset * 1000000);
        /* month m + 12 k of year y is month m of year y + k */
        over = base;
        over.month = (uint8_t)(base.month + 12 * (unsigned)rng_between(0, 20));
        over.year = base.year - (over.month - base.month) / 12;
        CHECK_EQ_I64(frc_time_from_civil(&over, 0), start);
    }
}

/* ------------------------------------------------------------------------- */
/* ISO text                                                                   */
/* ------------------------------------------------------------------------- */

static void test_format(void)
{
    static const char FULL[] = "2026-10-08T14:00:00.000+02:00";
    frc_civil_t c;
    char buf[64];
    size_t size;

    TEST_SECTION("frc_format_civil: typed in");
    /* the example of fractonica.h */
    frc_civil_from_time(FRC_TIME_FROM_S(INT64_C(1791460800)), 0, &c);
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), 24);
    CHECK_STR(buf, "2026-10-08T12:00:00.000Z");
    frc_civil_from_time(FRC_TIME_FROM_S(INT64_C(1791460800)), 7200, &c);
    CHECK_EQ_I64(frc_format_civil(&c, 7200, buf, sizeof buf), 29);
    CHECK_STR(buf, FULL);
    /* milliseconds are truncated, never rounded into the next second */
    c = civil(1999, 12, 31, 23, 59, 59, 999999);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "1999-12-31T23:59:59.999Z");
    c = civil(2000, 1, 1, 0, 0, 0, 999);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "2000-01-01T00:00:00.000Z");
    /* years outside 0..9999 carry a sign */
    c = civil(0, 1, 1, 0, 0, 0, 0);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "0000-01-01T00:00:00.000Z");
    c = civil(7, 3, 4, 5, 6, 7, 8000);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "0007-03-04T05:06:07.008Z");
    c = civil(9999, 12, 31, 23, 59, 59, 0);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "9999-12-31T23:59:59.000Z");
    c = civil(10000, 1, 1, 0, 0, 0, 0);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "+10000-01-01T00:00:00.000Z");
    c = civil(12345, 6, 7, 8, 9, 10, 0);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "+12345-06-07T08:09:10.000Z");
    c = civil(-44, 3, 15, 0, 0, 0, 0);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "-0044-03-15T00:00:00.000Z");
    c = civil(-12345, 6, 7, 8, 9, 10, 0);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "-12345-06-07T08:09:10.000Z");
    c = civil(INT32_MIN, 1, 1, 0, 0, 0, 0);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "-2147483648-01-01T00:00:00.000Z");
    c = civil(INT32_MAX, 1, 1, 0, 0, 0, 0);
    frc_format_civil(&c, 0, buf, sizeof buf);
    CHECK_STR(buf, "+2147483647-01-01T00:00:00.000Z");

    TEST_SECTION("frc_format_civil: offsets");
    c = civil(2026, 10, 8, 12, 0, 0, 0);
    frc_format_civil(&c, 19800, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000+05:30");
    frc_format_civil(&c, -34200, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000-09:30");
    frc_format_civil(&c, 50400, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000+14:00");
    frc_format_civil(&c, 60, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000+00:01");
    frc_format_civil(&c, -60, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000-00:01");
    /* an offset that is not whole minutes is cut towards zero and keeps its sign;
     * only an offset of exactly 0 is "Z" (the header does not say: this pins the choice) */
    frc_format_civil(&c, 90, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000+00:01");
    frc_format_civil(&c, -90, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000-00:01");
    frc_format_civil(&c, 59, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000+00:00");
    frc_format_civil(&c, -59, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000-00:00");
    frc_format_civil(&c, INT32_MAX, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000+596523:14");
    frc_format_civil(&c, INT32_MIN, buf, sizeof buf);
    CHECK_STR(buf, "2026-10-08T12:00:00.000-596523:14");

    TEST_SECTION("frc_format_civil: buffers");
    c = civil(2026, 10, 8, 14, 0, 0, 0);
    CHECK_EQ_U64(strlen(FULL), 29);
    CHECK_EQ_I64(frc_format_civil(&c, 7200, buf, 30), 29);
    CHECK_STR(buf, FULL);
    for (size = 1; size <= 29; size++) {
        memset(buf, '#', sizeof buf);
        CHECK_EQ_I64(frc_format_civil(&c, 7200, buf, size), FRC_ERR_BUFFER);
        CHECK_EQ_U64(strlen(buf), size - 1);          /* as much as fits */
        CHECK(memcmp(buf, FULL, size - 1) == 0);      /* a prefix of the text */
        CHECK(buf[size] == '#');                      /* nothing past the buffer */
    }
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, 0), FRC_ERR_BUFFER);
    CHECK_EQ_I64(frc_format_civil(&c, 0, NULL, 0), FRC_ERR_BUFFER);
    CHECK_EQ_I64(frc_format_civil(&c, 0, NULL, 64), FRC_ERR_BUFFER);

    TEST_SECTION("frc_format_civil: only a real date and time of day is written");
    snprintf(buf, sizeof buf, "junk");
    CHECK_EQ_I64(frc_format_civil(NULL, 0, buf, sizeof buf), FRC_ERR_ARG);
    CHECK_STR(buf, "");
    c = civil(2026, 0, 8, 12, 0, 0, 0);
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), FRC_ERR_ARG);
    c = civil(2026, 13, 8, 12, 0, 0, 0);
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), FRC_ERR_ARG);
    c = civil(2026, 10, 0, 12, 0, 0, 0);
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), FRC_ERR_ARG);
    c = civil(2026, 10, 32, 12, 0, 0, 0);
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), FRC_ERR_ARG);
    c = civil(2026, 10, 8, 24, 0, 0, 0);
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), FRC_ERR_ARG);
    c = civil(2026, 10, 8, 12, 60, 0, 0);
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), FRC_ERR_ARG);
    c = civil(2026, 10, 8, 12, 0, 60, 0);
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), FRC_ERR_ARG);
    c = civil(2026, 10, 8, 12, 0, 0, 1000000);
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), FRC_ERR_ARG);
    c = civil(2026, 10, 8, 12, 0, 0, 999999);
    c.weekday = 200; /* output only: not looked at */
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), 24);
    /* overflowing fields are normalised by the round trip, then they print */
    c = civil(2026, 12, 31, 23, 59, 60, 0);
    frc_civil_from_time(frc_time_from_civil(&c, 0), 0, &c);
    CHECK_EQ_I64(frc_format_civil(&c, 0, buf, sizeof buf), 24);
    CHECK_STR(buf, "2027-01-01T00:00:00.000Z");
}

/* ------------------------------------------------------------------------- */
/* SPEC S2.3                                                                  */
/* ------------------------------------------------------------------------- */

/* floor(a / b) for b > 0 */
static int64_t floor_div(int64_t a, int64_t b)
{
    return a / b - (a % b < 0 ? 1 : 0);
}

static void test_julian(void)
{
    unsigned i, library_differs = 0;

    TEST_SECTION("oracle_julian: the formula of SPEC S2.3 applied as it stands");
    for (i = 0; i < ORACLE_JULIAN_COUNT; i++) {
        const oracle_julian_t *v = &oracle_julian[i];
        CHECK_EQ_I64(frc_julian_fields_to_unix_ms(v->unix_ms), v->fixed_ms);
        CHECK_NOTE("julian vector %u: %" PRId64, i, v->unix_ms);
        if (v->library_ms != v->fixed_ms) {
            /* the reference library leaves instants from the reform on unchanged;
             * fractonica.h documents the bare reinterpretation, which this core returns */
            CHECK(v->unix_ms >= ORACLE_JULIAN_REFORM_MS);
            CHECK_EQ_I64(v->library_ms, v->unix_ms);
            library_differs++;
        } else {
            CHECK(v->unix_ms < ORACLE_JULIAN_REFORM_MS);
        }
    }
    CHECK_EQ_U64(library_differs, 7);

    TEST_SECTION("SPEC S2.3, typed in: 10 days near 1582, one day less per century before");
    /* 1582-10-04 (Julian, the eve of the reform) is 1582-10-14 Gregorian */
    CHECK_EQ_I64(frc_julian_fields_to_unix_ms(INT64_C(-12220243200000)) - INT64_C(-12220243200000), 10 * DAY_MS);
    /* 1453-05-29 is 9 days off; 1066-10-14 six; 0325-05-20 one; 0250 none */
    CHECK_EQ_I64(frc_julian_fields_to_unix_ms(INT64_C(-16302079503211)) - INT64_C(-16302079503211), 9 * DAY_MS);
    CHECK_EQ_I64(frc_julian_fields_to_unix_ms(INT64_C(-28502755200000)) - INT64_C(-28502755200000), 6 * DAY_MS);
    CHECK_EQ_I64(frc_julian_fields_to_unix_ms(INT64_C(-51899184000000)) - INT64_C(-51899184000000), 1 * DAY_MS);
    CHECK_EQ_I64(frc_julian_fields_to_unix_ms(INT64_C(-54264880799999)), INT64_C(-54264880799999));

    TEST_SECTION("the calendars differ by floor(Y/100) - floor(Y/400) - 2 days");
    for (i = 0; i < 100000; i++) {
        /* years -5000 .. 6000, to the millisecond */
        int64_t unix_ms = rng_between(-INT64_C(220000000000000), INT64_C(127000000000000));
        int64_t fixed = frc_julian_fields_to_unix_ms(unix_ms);
        frc_civil_t c;
        int64_t march_year, expected_days;
        frc_civil_from_time(unix_ms * 1000, 0, &c);
        march_year = c.month >= 3 ? c.year : c.year - 1; /* the leap day ends the year */
        expected_days = floor_div(march_year, 100) - floor_div(march_year, 400) - 2;
        CHECK_EQ_I64(fixed - unix_ms, expected_days * DAY_MS);
        CHECK_NOTE("unix_ms %" PRId64 " (%d-%02u-%02u)", unix_ms, c.year, c.month, c.day);
    }

    TEST_SECTION("frc_julian_fields_to_unix_ms: far values come back");
    /* no date is promised out here, but nothing may trap; the shift stays whole days where it fits */
    (void)frc_julian_fields_to_unix_ms(INT64_MAX);
    (void)frc_julian_fields_to_unix_ms(INT64_MIN);
    CHECK_EQ_I64((frc_julian_fields_to_unix_ms(INT64_C(1) << 55) - (INT64_C(1) << 55)) % DAY_MS, 0);
    CHECK_EQ_I64((frc_julian_fields_to_unix_ms(-(INT64_C(1) << 55)) - -(INT64_C(1) << 55)) % DAY_MS, 0);
}

int main(void)
{
    test_oracle_civil();
    test_oracle_roll();
    test_walk();
    test_round_trips();
    test_format();
    test_julian();
    return TEST_SUMMARY("civil");
}
